-- V90.ch GST return operations/compliance workflow tables are created idempotently by app bootstrap.
CREATE TABLE IF NOT EXISTS gst_compliance_returns(return_id TEXT PRIMARY KEY, filing_id TEXT NOT NULL, return_type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PREPARED', outward_tax NUMERIC NOT NULL DEFAULT 0, inward_tax NUMERIC NOT NULL DEFAULT 0, net_tax NUMERIC NOT NULL DEFAULT 0, amendment_count INTEGER NOT NULL DEFAULT 0, prepared_by TEXT NOT NULL, prepared_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, filed_at TIMESTAMP, filing_reference TEXT, UNIQUE(filing_id,return_type));
CREATE TABLE IF NOT EXISTS gst_compliance_documents(document_id TEXT PRIMARY KEY, filing_id TEXT NOT NULL, document_type TEXT NOT NULL, document_ref TEXT, taxable_value NUMERIC NOT NULL DEFAULT 0, tax_value NUMERIC NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'INCLUDED', created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
